CREATE TABLE retail_activation (id integer PRIMARY KEY CHECK(id=1), request jsonb, code text, state jsonb NOT NULL DEFAULT '{}', mac text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_counters(company_id uuid NOT NULL REFERENCES companies(id), kind text NOT NULL, value bigint NOT NULL, PRIMARY KEY(company_id,kind));
CREATE TABLE partners(company_id uuid NOT NULL REFERENCES companies(id), id text NOT NULL, kind text NOT NULL CHECK(kind IN('customer','supplier')), name text NOT NULL, credit_limit numeric(24,9) NOT NULL DEFAULT 0 CHECK(credit_limit>=0), data jsonb NOT NULL DEFAULT '{}', archived_at timestamptz, PRIMARY KEY(company_id,id));
CREATE INDEX partner_search ON partners(company_id,kind,lower(name));
CREATE TABLE cashboxes(company_id uuid NOT NULL, id uuid NOT NULL, branch_id uuid NOT NULL, name text NOT NULL, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id));
CREATE TABLE shifts(company_id uuid NOT NULL, id uuid NOT NULL, cashbox_id uuid NOT NULL, user_id uuid NOT NULL, device_id text NOT NULL, opening numeric(24,9) NOT NULL CHECK(opening>=0), opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, close_snapshot jsonb, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,cashbox_id) REFERENCES cashboxes(company_id,id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
CREATE UNIQUE INDEX one_open_cashbox ON shifts(company_id,cashbox_id) WHERE closed_at IS NULL;
CREATE UNIQUE INDEX one_open_device ON shifts(company_id,device_id) WHERE closed_at IS NULL;
CREATE TABLE commercial_orders(company_id uuid NOT NULL, id uuid NOT NULL, number text NOT NULL, kind text NOT NULL CHECK(kind IN('quotation','order')), warehouse_id uuid NOT NULL, partner_id text, source_id uuid, snapshot jsonb NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,id), UNIQUE(company_id,number), UNIQUE(company_id,source_id), FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id), FOREIGN KEY(company_id,partner_id) REFERENCES partners(company_id,id), FOREIGN KEY(company_id,source_id) REFERENCES commercial_orders(company_id,id), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id));
CREATE TABLE commercial_deliveries(company_id uuid NOT NULL, id uuid NOT NULL, order_id uuid NOT NULL, number text NOT NULL, snapshot jsonb NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,id), UNIQUE(company_id,number), FOREIGN KEY(company_id,order_id) REFERENCES commercial_orders(company_id,id), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id));
CREATE TABLE delivery_allocations(company_id uuid NOT NULL, delivery_id uuid NOT NULL, line_id text NOT NULL, quantity numeric(24,9) NOT NULL CHECK(quantity>0), invoiced numeric(24,9) NOT NULL DEFAULT 0 CHECK(invoiced>=0 AND invoiced<=quantity), cost numeric(24,9) NOT NULL CHECK(cost>=0), PRIMARY KEY(company_id,delivery_id,line_id), FOREIGN KEY(company_id,delivery_id) REFERENCES commercial_deliveries(company_id,id));
CREATE TABLE commercial_documents(company_id uuid NOT NULL, id uuid NOT NULL, number text NOT NULL, kind text NOT NULL CHECK(kind IN('sale','purchase','sale_return','purchase_return')), warehouse_id uuid NOT NULL, partner_id text, shift_id uuid, original_id uuid, order_id uuid, currency text NOT NULL REFERENCES currencies(code), exchange_rate numeric(24,10) NOT NULL CHECK(exchange_rate>0), subtotal numeric(24,9) NOT NULL CHECK(subtotal>=0), discount numeric(24,9) NOT NULL CHECK(discount>=0), tax numeric(24,9) NOT NULL CHECK(tax>=0), total numeric(24,9) NOT NULL CHECK(total>=0), total_base numeric(24,9) NOT NULL CHECK(total_base>=0), cost_base numeric(24,9) NOT NULL CHECK(cost_base>=0), snapshot jsonb NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,id), UNIQUE(company_id,number), FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id), FOREIGN KEY(company_id,partner_id) REFERENCES partners(company_id,id), FOREIGN KEY(company_id,shift_id) REFERENCES shifts(company_id,id), FOREIGN KEY(company_id,original_id) REFERENCES commercial_documents(company_id,id), FOREIGN KEY(company_id,order_id) REFERENCES commercial_orders(company_id,id), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id));
CREATE INDEX commercial_history ON commercial_documents(company_id,created_at DESC,id);
CREATE INDEX commercial_partner ON commercial_documents(company_id,partner_id,created_at,id);
CREATE TABLE commercial_lines(company_id uuid NOT NULL, document_id uuid NOT NULL, id text NOT NULL, product_id text NOT NULL, variant_id text NOT NULL DEFAULT '', unit_id text NOT NULL, quantity numeric(24,9) NOT NULL CHECK(quantity>0), original_line_id text, snapshot jsonb NOT NULL, PRIMARY KEY(company_id,document_id,id), FOREIGN KEY(company_id,document_id) REFERENCES commercial_documents(company_id,id), FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id));
CREATE TABLE document_cancellations(company_id uuid NOT NULL, document_id uuid NOT NULL, reversal_id uuid NOT NULL, reason text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,document_id), FOREIGN KEY(company_id,document_id) REFERENCES commercial_documents(company_id,id), FOREIGN KEY(company_id,reversal_id) REFERENCES commercial_documents(company_id,id), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id));
CREATE TABLE payments(company_id uuid NOT NULL, id uuid NOT NULL, number text NOT NULL, partner_id text, document_id uuid, shift_id uuid, direction text NOT NULL CHECK(direction IN('in','out')), method text NOT NULL CHECK(method IN('cash','card','transfer')), currency text NOT NULL REFERENCES currencies(code), amount numeric(24,9) NOT NULL CHECK(amount>0), exchange_rate numeric(24,10) NOT NULL CHECK(exchange_rate>0), amount_base numeric(24,9) NOT NULL CHECK(amount_base>0), fx_base numeric(24,9) NOT NULL DEFAULT 0, snapshot jsonb NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,id), UNIQUE(company_id,number), FOREIGN KEY(company_id,partner_id) REFERENCES partners(company_id,id), FOREIGN KEY(company_id,document_id) REFERENCES commercial_documents(company_id,id), FOREIGN KEY(company_id,shift_id) REFERENCES shifts(company_id,id), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id));
CREATE TABLE payment_allocations(company_id uuid NOT NULL, payment_id uuid NOT NULL, document_id uuid NOT NULL, amount numeric(24,9) NOT NULL CHECK(amount>0), carrying_base numeric(24,9) NOT NULL CHECK(carrying_base>0), settlement_base numeric(24,9) NOT NULL CHECK(settlement_base>0), PRIMARY KEY(company_id,payment_id,document_id), FOREIGN KEY(company_id,payment_id) REFERENCES payments(company_id,id), FOREIGN KEY(company_id,document_id) REFERENCES commercial_documents(company_id,id));
CREATE TABLE partner_entries(id uuid PRIMARY KEY, company_id uuid NOT NULL, partner_id text NOT NULL, document_id uuid, payment_id uuid, amount_base numeric(24,9) NOT NULL, currency text NOT NULL REFERENCES currencies(code), amount numeric(24,9) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,partner_id) REFERENCES partners(company_id,id), FOREIGN KEY(company_id,document_id) REFERENCES commercial_documents(company_id,id), FOREIGN KEY(company_id,payment_id) REFERENCES payments(company_id,id), CHECK(document_id IS NOT NULL OR payment_id IS NOT NULL));
CREATE INDEX partner_statement ON partner_entries(company_id,partner_id,created_at,id);
CREATE TABLE cash_entries(id uuid PRIMARY KEY, company_id uuid NOT NULL, shift_id uuid NOT NULL, payment_id uuid NOT NULL, currency text NOT NULL REFERENCES currencies(code), amount numeric(24,9) NOT NULL, amount_base numeric(24,9) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,payment_id), FOREIGN KEY(company_id,shift_id) REFERENCES shifts(company_id,id), FOREIGN KEY(company_id,payment_id) REFERENCES payments(company_id,id));
CREATE TABLE print_jobs(company_id uuid NOT NULL, id uuid NOT NULL, document_id uuid, kind text NOT NULL CHECK(kind IN('receipt','return','invoice','labels')), format text NOT NULL CHECK(format IN('58mm','80mm','A4','40x30','50x30')), payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','acknowledged','failed')), attempts integer NOT NULL DEFAULT 0, acknowledged_by uuid, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,document_id) REFERENCES commercial_documents(company_id,id), FOREIGN KEY(company_id,acknowledged_by) REFERENCES users(company_id,id));
CREATE TABLE legacy_commercial_batches(company_id uuid NOT NULL REFERENCES companies(id), id uuid NOT NULL, content_hash text NOT NULL, original_data jsonb NOT NULL, report jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,id), UNIQUE(company_id,content_hash));
CREATE TABLE legacy_commercial_records(company_id uuid NOT NULL, batch_id uuid NOT NULL, collection text NOT NULL, legacy_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(company_id,collection,legacy_id), FOREIGN KEY(company_id,batch_id) REFERENCES legacy_commercial_batches(company_id,id));
CREATE TRIGGER immutable_documents BEFORE UPDATE OR DELETE ON commercial_documents FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_lines BEFORE UPDATE OR DELETE ON commercial_lines FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_payments BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_allocations BEFORE UPDATE OR DELETE ON payment_allocations FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_partner_entries BEFORE UPDATE OR DELETE ON partner_entries FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_cash_entries BEFORE UPDATE OR DELETE ON cash_entries FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_orders BEFORE UPDATE OR DELETE ON commercial_orders FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER immutable_deliveries BEFORE UPDATE OR DELETE ON commercial_deliveries FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
ALTER TABLE stock_ledger ADD COLUMN reversal_of uuid REFERENCES stock_ledger(id);
